var t=`1343-pique-macho`;var n=`world-1343`;var i=`BO`;var a=`south-america`;var s=4;var r=51;var u={en:`Pique Macho`,ua:`Піке мачо`};var d={en:`Pique Macho is a dish from Bolivia featuring beef sirloin, potato, fresh pork sausage, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Піке мачо, страва кухні країни Болівія з такими основними складниками: яловичий сирлойн, картопля, сира свиняча ковбаса, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 14 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 14 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:14,i:[[`beef-sirloin`,650,`g`],[`canola-oil`,50,`ml`],[`ground-cumin`,5,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`potato`,580,`g`],[`canola-oil`,140,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`fresh-pork-sausage`,300,`g`],[`yellow-onion`,170,`g`],[`tomato`,210,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Fry the eggs over medium heat until the whites are set and the yolks reach the desired safely cooked firmness; use a lightly oiled non-stick pan.`,ua:`Смажте яйця на середньому вогні до повного схоплення білків і безпечної готовності жовтків; використовуйте злегка змащену антипригарну сковороду.`,t:[`pan-frying`],m:7,i:[[`chicken-egg`,4,`pcs`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`hot-sauce`,60,`ml`]]}];var h={slug:t,id:n,country:`BO`,region:a,servings:4,minutes:51,title:u,text:d,steps:l};export{i as country,h as default,n as id,r as minutes,a as region,s as servings,t as slug,l as steps,d as text,u as title};